import {Worker, isMainThread, parentPort, workerData} from 'node:worker_threads';
import {mkdtempSync, readFileSync, rmSync} from 'node:fs';
import {createCompilerProfile} from '/tmp/bend2039-profile-scopes/evals/compiler_profile.mjs';
const burn = () => {let answer=0; for(let i=0;i<2_000_000;i++) answer += Math.sqrt(i); return answer;};
const directory=isMainThread?mkdtempSync('/tmp/bend2039-profile-boundary-evidence-'):workerData.directory;
const profile=await createCompilerProfile({directory,execution:{stage:'actual-worker-boundary-smoke'},sampling:false});
const span=profile.begin(isMainThread?'worker-and-parent':'worker-work');
if (!isMainThread) {
  const answer=burn(); profile.end(span); const summary=profile.finish();
  parentPort.postMessage({answer,summary});
} else {
  const worker=new Worker(new URL(import.meta.url),{workerData:{directory}});
  const result=await new Promise((resolve,reject)=>{worker.once('message',resolve);worker.once('error',reject);});
  profile.end(span);const summary=profile.finish();await worker.terminate();
  if(result.summary.identity.pid!==summary.identity.pid || result.summary.identity.threadId===summary.identity.threadId || result.answer!==burn()) throw Error('worker identity/result mismatch');
  const reports=[summary,result.summary];
  for(const report of reports){
    const memory=report.spans[0].boundaryMemory;
    if(memory.delta.allocationVolume.status!=='unavailable')throw Error('unverified allocation counter was published');
    if(memory.start.unavailable.liveHeapBytes.status!=='unavailable'||memory.start.unavailable.footprintBytes.status!=='unavailable')throw Error('unknown memory class was published');
    if(process.versions.bun && memory.start.heapStatistics.status!=='unavailable')throw Error('Bun shim received V8 semantics');
    if(!process.versions.bun && memory.start.heapStatistics.status!=='available')throw Error('V8 boundary evidence lost');
    if(report.status!=='completed'||report.measurementStatus!=='complete')throw Error('incomplete collector result');
  }
  console.log(JSON.stringify({status:'PASS',runtime:summary.runtime,profiles:reports.map(report=>({identity:report.identity,cpu:report.spans[0].cpu,memory:report.spans[0].boundaryMemory,provenance:report.provenance})),note:'Behavioral smoke only; no full-root overhead or isolated provider attribution.'}));
  rmSync(directory,{recursive:true});
}
